// src/components/AdminPanel.js
import React from "react";

function AdminPanel({ candidateForm, setCandidateForm, onSave, theme }) {

  // 🔥 Available Positions
  const positions = [
    "President",
    "Vice President",
    "Secretary",
    "Treasurer",
    "Auditor",
    "Other",
  ];

  // 🔥 Year Levels
  const yearLevels = [
    "1st Year",
    "2nd Year",
    "3rd Year",
    "4th Year",
  ];

  // 🔥 Blocks
  const blocks = [
    "Block 1",
    "Block 2",
    "Block 3",
  ];

  return (
    <div
      style={{
        padding: 20,
        borderRadius: 10,
        backgroundColor: theme.card,
        boxShadow: darkModeShadow(theme),
        display: "flex",
        flexDirection: "column",
        gap: 12,
      }}
    >
      <h3 style={{ marginBottom: 12, color: theme.text }}>
        Add / Edit Candidate
      </h3>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={{ display: "flex", flexDirection: "column", gap: 10 }}
      >
        {/* First Name */}
        <input
          type="text"
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        {/* Last Name */}
        <input
          type="text"
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        {/* 🔥 Candidacy Position */}
        <select
          value={candidateForm.candidacy}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, candidacy: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Candidacy Position</option>
          {positions.map((pos) => (
            <option key={pos} value={pos}>
              {pos}
            </option>
          ))}
        </select>

        {/* 🔥 Year Level */}
        <select
          value={candidateForm.yearLevel || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, yearLevel: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Year Level</option>
          {yearLevels.map((year) => (
            <option key={year} value={year}>
              {year}
            </option>
          ))}
        </select>

        {/* 🔥 Block */}
        <select
          value={candidateForm.block || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, block: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Block</option>
          {blocks.map((block) => (
            <option key={block} value={block}>
              {block}
            </option>
          ))}
        </select>

        {/* Description */}
        <textarea
          placeholder="Description"
          value={candidateForm.description || ""}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, description: e.target.value })
          }
          style={textareaStyle(theme)}
        />

        {/* Image Upload */}
        <input
          type="file"
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, image: e.target.files[0] })
          }
          style={{ marginTop: 4 }}
        />

        {/* Save Button */}
        <button
          type="submit"
          style={{
            marginTop: 10,
            padding: "8px 12px",
            borderRadius: 6,
            border: "none",
            backgroundColor: theme.button,
            color: theme.buttonText,
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          Save Candidate
        </button>
      </form>
    </div>
  );
}

// =================== STYLES ===================

const inputStyle = (theme) => ({
  padding: 8,
  borderRadius: 6,
  border: `1px solid ${theme.text}33`,
  width: "100%",
  backgroundColor: theme.background,
  color: theme.text,
});

const textareaStyle = (theme) => ({
  padding: 8,
  borderRadius: 6,
  border: `1px solid ${theme.text}33`,
  width: "100%",
  minHeight: 80,
  backgroundColor: theme.background,
  color: theme.text,
});

const darkModeShadow = (theme) =>
  theme.background === "#1f1f2e"
    ? "0 2px 8px rgba(255,255,255,0.05)"
    : "0 2px 8px rgba(0,0,0,0.2)";

export default AdminPanel;
